// Kover code coverage support for modules with tests (E00-06). Every module applying this
// plugin automatically contributes to the aggregate coverage report (applied to all
// android/core/* and android/feature/* modules, plus android/app, which have test suites).
// The aggregate report is generated by the root build's koverHtmlReport task.
plugins {
    id("org.jetbrains.kotlinx.kover")
}
